1	// This module provides a data structure, `Ignore`, that connects "directory
2	// traversal" with "ignore matchers." Specifically, it knows about gitignore
3	// semantics and precedence, and is organized based on directory hierarchy.
4	// Namely, every matcher logically corresponds to ignore rules from a single
5	// directory, and points to the matcher for its corresponding parent directory.
6	// In this sense, `Ignore` is a *persistent* data structure.
7	//
8	// This design was specifically chosen to make it possible to use this data
9	// structure in a parallel directory iterator.
10	//
11	// My initial intention was to expose this module as part of this crate's
12	// public API, but I think the data structure's public API is too complicated
13	// with non-obvious failure modes. Alas, such things haven't been documented
14	// well.
15	
16	use std::{
17	    collections::HashMap,
18	    ffi::{OsStr, OsString},
19	    fs::{self, File, FileType},
20	    io::{self, BufRead},
21	    path::{Path, PathBuf},
22	    sync::{Arc, RwLock, Weak},
23	};
24	
25	use crate::{
26	    gitignore::{self, Gitignore, GitignoreBuilder},
27	    overrides::{self, Override},
28	    pathutil::{is_hidden_entry, strip_prefix},
29	    types::{self, Types},
30	    walk::DirEntry,
31	    {Error, Match, PartialErrorBuilder},
32	};
33	
34	/// IgnoreMatch represents information about where a match came from when using
35	/// the `Ignore` matcher.
36	#[derive(Clone, Debug)]
37	#[allow(dead_code)]
38	pub(crate) struct IgnoreMatch<'a>(IgnoreMatchInner<'a>);
39	
40	/// IgnoreMatchInner describes precisely where the match information came from.
41	/// This is private to allow expansion to more matchers in the future.
42	#[derive(Clone, Debug)]
43	#[allow(dead_code)]
44	enum IgnoreMatchInner<'a> {
45	    Override(overrides::Glob<'a>),
46	    Gitignore(&'a gitignore::Glob),
47	    Types(types::Glob<'a>),
48	    Hidden,
49	}
50	
51	impl<'a> IgnoreMatch<'a> {
52	    fn overrides(x: overrides::Glob<'a>) -> IgnoreMatch<'a> {
53	        IgnoreMatch(IgnoreMatchInner::Override(x))
54	    }
55	
56	    fn gitignore(x: &'a gitignore::Glob) -> IgnoreMatch<'a> {
57	        IgnoreMatch(IgnoreMatchInner::Gitignore(x))
58	    }
59	
60	    fn types(x: types::Glob<'a>) -> IgnoreMatch<'a> {
61	        IgnoreMatch(IgnoreMatchInner::Types(x))
62	    }
63	
64	    fn hidden() -> IgnoreMatch<'static> {
65	        IgnoreMatch(IgnoreMatchInner::Hidden)
66	    }
67	}
68	
69	/// Options for the ignore matcher, shared between the matcher itself and the
70	/// builder.
71	#[derive(Clone, Copy, Debug)]
72	struct IgnoreOptions {
73	    /// Whether to ignore hidden file paths or not.
74	    hidden: bool,
75	    /// Whether to read .ignore files.
76	    ignore: bool,
77	    /// Whether to respect any ignore files in parent directories.
78	    parents: bool,
79	    /// Whether to read git's global gitignore file.
80	    git_global: bool,
81	    /// Whether to read .gitignore files.
82	    git_ignore: bool,
83	    /// Whether to read .git/info/exclude files.
84	    git_exclude: bool,
85	    /// Whether to ignore files case insensitively
86	    ignore_case_insensitive: bool,
87	    /// Whether a git repository must be present in order to apply any
88	    /// git-related ignore rules.
89	    require_git: bool,
90	}
91	
92	/// Ignore is a matcher useful for recursively walking one or more directories.
93	#[derive(Clone, Debug)]
94	pub(crate) struct Ignore {
95	    inner: Arc<IgnoreInner>,
96	    // Parent matchers are cached independently of the path being walked, but
97	    // matching them still needs the canonicalized path originally passed to
98	    // `add_parents`. For example, when walking `/tmp/project/src`, parent
99	    // matchers use `/tmp/project/src` to rewrite `/tmp/project/src/foo.py`
100	    // before matching it against ignore files from `/tmp/project` and its
101	    // ancestors.
102	    //
103	    // For ripgrep itself, this means that `rg pat src tests` must rewrite
104	    // `src/foo` relative to `.../src`, and not whatever root was prepared
105	    // first.
106	    //
107	    // See: https://github.com/BurntSushi/ripgrep/pull/3420
108	    // See: https://github.com/BurntSushi/ripgrep/issues/3376
109	    // See: https://github.com/BurntSushi/ripgrep/issues/3419
110	    // See: https://github.com/BurntSushi/ripgrep/issues/3320
111	    absolute_base: Option<Arc<PathBuf>>,
112	}
113	
114	#[derive(Clone, Debug)]
115	struct IgnoreInner {
116	    /// A map of all existing directories that have already been
117	    /// compiled into matchers.
118	    ///
119	    /// Note that this is never used during matching, only when adding new
120	    /// parent directory matchers. This avoids needing to rebuild glob sets for
121	    /// parent directories if many paths are being searched.
122	    compiled: Arc<RwLock<HashMap<OsString, Weak<IgnoreInner>>>>,
123	    /// The path to the directory that this matcher was built from.
124	    dir: PathBuf,
125	    /// An override matcher (default is empty).
126	    overrides: Arc<Override>,
127	    /// A file type matcher.
128	    types: Arc<Types>,
129	    /// The parent directory to match next.
130	    ///
131	    /// If this is the root directory or there are otherwise no more
132	    /// directories to match, then `parent` is `None`.
133	    parent: Option<Arc<IgnoreInner>>,
134	    /// Whether this is an absolute parent matcher, as added by add_parent.
135	    is_absolute_parent: bool,
136	    /// The directory that gitignores should be interpreted relative to.
137	    ///
138	    /// Usually this is the directory containing the gitignore file. But in
139	    /// some cases, like for global gitignores or for gitignores specified
140	    /// explicitly, this should generally be set to the current working
141	    /// directory. This is only used for global gitignores or "explicit"
142	    /// gitignores.
143	    ///
144	    /// When `None`, this means the CWD could not be determined or is unknown.
145	    /// In this case, global gitignore files are ignored because they otherwise
146	    /// cannot be matched correctly.
147	    global_gitignores_relative_to: Option<PathBuf>,
148	    /// Explicit global ignore matchers specified by the caller.
149	    explicit_ignores: Arc<Vec<Gitignore>>,
150	    /// Ignore files used in addition to `.ignore`
151	    custom_ignore_filenames: Arc<Vec<OsString>>,
152	    /// The matcher for custom ignore files
153	    custom_ignore_matcher: Gitignore,
154	    /// The matcher for .ignore files.
155	    ignore_matcher: Gitignore,
156	    /// A global gitignore matcher, usually from $XDG_CONFIG_HOME/git/ignore.
157	    git_global_matcher: Arc<Gitignore>,
158	    /// The matcher for .gitignore files.
159	    git_ignore_matcher: Gitignore,
160	    /// Special matcher for `.git/info/exclude` files.
161	    git_exclude_matcher: Gitignore,
162	    /// Whether this directory contains a .git sub-directory.
163	    has_git: bool,
164	    /// Ignore config.
165	    opts: IgnoreOptions,
166	}
167	
168	impl Ignore {
169	    /// Return the directory path of this matcher.
170	    #[cfg(test)]
171	    pub(crate) fn path(&self) -> &Path {
172	        &self.inner.dir
173	    }
174	
175	    /// Return true if this matcher has no parent.
176	    pub(crate) fn is_root(&self) -> bool {
177	        self.inner.parent.is_none()
178	    }
179	
180	    /// Return this matcher's parent, if one exists.
181	    pub(crate) fn parent(&self) -> Option<Ignore> {
182	        self.inner.parent.as_ref().map(|parent| Ignore {
183	            inner: parent.clone(),
184	            absolute_base: self.absolute_base.clone(),
185	        })
186	    }
187	
188	    /// Create a new `Ignore` matcher with the parent directories of `dir`.
189	    ///
190	    /// Note that this can only be called on an `Ignore` matcher with no
191	    /// parents (i.e., `is_root` returns `true`). This will panic otherwise.
192	    pub(crate) fn add_parents<P: AsRef<Path>>(
193	        &self,
194	        path: P,
195	    ) -> (Ignore, Option<Error>) {
196	        if !self.inner.opts.parents
197	            && !self.inner.opts.git_ignore
198	            && !self.inner.opts.git_exclude
199	            && !self.inner.opts.git_global
200	        {
201	            // If we never need info from parent directories, then don't do
202	            // anything.
203	            return (self.clone(), None);
204	        }
205	        if !self.is_root() {
206	            panic!("Ignore::add_parents called on non-root matcher");
207	        }
208	        let absolute_base = match path.as_ref().canonicalize() {
209	            Ok(path) => Arc::new(path),
210	            Err(_) => {
211	                // There's not much we can do here, so just return our
212	                // existing matcher. We drop the error to be consistent
213	                // with our general pattern of ignoring I/O errors when
214	                // processing ignore files.
215	                return (self.clone(), None);
216	            }
217	        };
218	        // List of parents, from child to root.
219	        let mut parents = vec![];
220	        let mut path = &**absolute_base;
221	        while let Some(parent) = path.parent() {
222	            parents.push(parent);
223	            path = parent;
224	        }
225	        let mut errs = PartialErrorBuilder::default();
226	        let mut ig = self.clone();
227	        for parent in parents.into_iter().rev() {
228	            let mut compiled = self.inner.compiled.write().unwrap();
229	            if let Some(weak) = compiled.get(parent.as_os_str()) {
230	                if let Some(prebuilt) = weak.upgrade() {
231	                    ig = Ignore {
232	                        inner: prebuilt,
233	                        absolute_base: Some(absolute_base.clone()),
234	                    };
235	                    continue;
236	                }
237	            }
238	            let (mut igtmp, err) = ig.add_child_path(parent);
239	            errs.maybe_push(err);
240	            igtmp.is_absolute_parent = true;
241	            igtmp.has_git =
242	                if self.inner.opts.require_git && self.inner.opts.git_ignore {
243	                    parent.join(".git").exists() || parent.join(".jj").exists()
244	                } else {
245	                    false
246	                };
247	            let ig_arc = Arc::new(igtmp);
248	            ig = Ignore {
249	                inner: ig_arc.clone(),
250	                absolute_base: Some(absolute_base.clone()),
251	            };
252	            compiled.insert(
253	                parent.as_os_str().to_os_string(),
254	                Arc::downgrade(&ig_arc),
255	            );
256	        }
257	        (ig, errs.into_error_option())
258	    }
259	
260	    /// Create a new `Ignore` matcher for the given child directory.
261	    ///
262	    /// Since building the matcher may require reading from multiple
263	    /// files, it's possible that this method partially succeeds. Therefore,
264	    /// a matcher is always returned (which may match nothing) and an error is
265	    /// returned if it exists.
266	    ///
267	    /// Note that all I/O errors are completely ignored.
268	    pub(crate) fn add_child<P: AsRef<Path>>(
269	        &self,
270	        dir: P,
271	    ) -> (Ignore, Option<Error>) {
272	        let (ig, err) = self.add_child_path(dir.as_ref());
273	        (
274	            Ignore {
275	                inner: Arc::new(ig),
276	                absolute_base: self.absolute_base.clone(),
277	            },
278	            err,
279	        )
280	    }
281	
282	    /// Like add_child, but uses successful read_dir entries to reduce
283	    /// probing when discovering ignore files.
284	    pub(crate) fn add_child_with_entries<P: AsRef<Path>>(
285	        &self,
286	        dir: P,
287	        entries: &[fs::DirEntry],
288	    ) -> (Ignore, Option<Error>) {
289	        let files = self.collect_ignore_files(entries);
290	        let (ig, err) = self.add_child_path_with_found_ignore_files(
291	            dir.as_ref(),
292	            Some(&files),
293	        );
294	        (
295	            Ignore {
296	                inner: Arc::new(ig),
297	                absolute_base: self.absolute_base.clone(),
298	            },
299	            err,
300	        )
301	    }
302	
303	    /// Like add_child, but takes a full path and returns an IgnoreInner.
304	    fn add_child_path(&self, dir: &Path) -> (IgnoreInner, Option<Error>) {
305	        self.add_child_path_with_found_ignore_files(dir, None)
306	    }
307	
308	    fn collect_ignore_files(
309	        &self,
310	        entries: &[fs::DirEntry],
311	    ) -> IgnoreFilesFound {
312	        let custom_ignore_filenames = &self.inner.custom_ignore_filenames;
313	        let mut files = IgnoreFilesFound {
314	            has_ignore: false,
315	            has_git_ignore: false,
316	            has_git_dir: false,
317	            has_jj_dir: false,
318	            custom_ignore_files: vec![false; custom_ignore_filenames.len()],
319	        };
320	        for entry in entries {
321	            let file_name = entry.file_name();
322	            if file_name == OsStr::new(".ignore") {
323	                files.has_ignore = true;
324	            } else if file_name == OsStr::new(".gitignore") {
325	                files.has_git_ignore = true;
326	            } else if file_name == OsStr::new(".git") {
327	                files.has_git_dir = true;
328	            } else if file_name == OsStr::new(".jj") {
329	                files.has_jj_dir = true;
330	            }
331	            for (i, name) in custom_ignore_filenames.iter().enumerate() {
332	                if file_name == name.as_os_str() {
333	                    files.custom_ignore_files[i] = true;
334	                }
335	            }
336	        }
337	        files
338	    }
339	
340	    fn add_child_path_with_found_ignore_files(
341	        &self,
342	        dir: &Path,
343	        ignore_files_list: Option<&IgnoreFilesFound>,
344	    ) -> (IgnoreInner, Option<Error>) {
345	        let check_vcs_dir = self.inner.opts.require_git
346	            && (self.inner.opts.git_ignore || self.inner.opts.git_exclude);
347	        let git_type = if check_vcs_dir
348	            && ignore_files_list.is_none_or(|i| i.has_git_dir)
349	        {
350	            dir.join(".git").metadata().ok().map(|md| md.file_type())
351	        } else {
352	            None
353	        };
354	        let has_jj = check_vcs_dir
355	            && ignore_files_list.is_none_or(|i| i.has_jj_dir)
356	            && dir.join(".jj").exists();
357	        let has_git = check_vcs_dir && (git_type.is_some() || has_jj);
358	
359	        let mut errs = PartialErrorBuilder::default();
360	        let custom_ig_matcher = if self
361	            .inner
362	            .custom_ignore_filenames
363	            .is_empty()
364	        {
365	            Gitignore::empty()
366	        } else {
367	            let custom_ignore_names: Vec<&OsString> = match ignore_files_list {
368	                None => self.inner.custom_ignore_filenames.iter().collect(),
369	                Some(m) => self
370	                    .inner
371	                    .custom_ignore_filenames
372	                    .iter()
373	                    .zip(m.custom_ignore_files.iter())
374	                    .filter(|&(_, &matched)| matched)
375	                    .map(|(name, _)| name)
376	                    .collect(),
377	            };
378	            if custom_ignore_names.is_empty() {
379	                Gitignore::empty()
380	            } else {
381	                let (m, err) = create_gitignore(
382	                    &dir,
383	                    &dir,
384	                    &custom_ignore_names,
385	                    self.inner.opts.ignore_case_insensitive,
386	                );
387	                errs.maybe_push(err);
388	                m
389	            }
390	        };
391	        let ig_matcher = if !self.inner.opts.ignore
392	            || !ignore_files_list.is_none_or(|i| i.has_ignore)
393	        {
394	            Gitignore::empty()
395	        } else {
396	            let (m, err) = create_gitignore(
397	                &dir,
398	                &dir,
399	                &[".ignore"],
400	                self.inner.opts.ignore_case_insensitive,
401	            );
402	            errs.maybe_push(err);
403	            m
404	        };
405	        let gi_matcher = if !self.inner.opts.git_ignore
406	            || !ignore_files_list.is_none_or(|i| i.has_git_ignore)
407	        {
408	            Gitignore::empty()
409	        } else {
410	            let (m, err) = create_gitignore(
411	                &dir,
412	                &dir,
413	                &[".gitignore"],
414	                self.inner.opts.ignore_case_insensitive,
415	            );
416	            errs.maybe_push(err);
417	            m
418	        };
419	
420	        let gi_exclude_matcher = if !self.inner.opts.git_exclude
421	            || !ignore_files_list.is_none_or(|i| i.has_git_dir)
422	        {
423	            Gitignore::empty()
424	        } else {
425	            match resolve_git_commondir(dir, git_type) {
426	                Ok(git_dir) => {
427	                    let (m, err) = create_gitignore(
428	                        &dir,
429	                        &git_dir,
430	                        &["info/exclude"],
431	                        self.inner.opts.ignore_case_insensitive,
432	                    );
433	                    errs.maybe_push(err);
434	                    m
435	                }
436	                Err(err) => {
437	                    errs.maybe_push(err);
438	                    Gitignore::empty()
439	                }
440	            }
441	        };
442	        let ig = IgnoreInner {
443	            compiled: self.inner.compiled.clone(),
444	            dir: dir.to_path_buf(),
445	            overrides: self.inner.overrides.clone(),
446	            types: self.inner.types.clone(),
447	            parent: Some(self.inner.clone()),
448	            is_absolute_parent: false,
449	            global_gitignores_relative_to: self
450	                .inner
451	                .global_gitignores_relative_to
452	                .clone(),
453	            explicit_ignores: self.inner.explicit_ignores.clone(),
454	            custom_ignore_filenames: self
455	                .inner
456	                .custom_ignore_filenames
457	                .clone(),
458	            custom_ignore_matcher: custom_ig_matcher,
459	            ignore_matcher: ig_matcher,
460	            git_global_matcher: self.inner.git_global_matcher.clone(),
461	            git_ignore_matcher: gi_matcher,
462	            git_exclude_matcher: gi_exclude_matcher,
463	            has_git,
464	            opts: self.inner.opts,
465	        };
466	        (ig, errs.into_error_option())
467	    }
468	
469	    /// Returns true if at least one type of ignore rule should be matched.
470	    fn has_any_ignore_rules(&self) -> bool {
471	        let opts = self.inner.opts;
472	        let has_custom_ignore_files =
473	            !self.inner.custom_ignore_filenames.is_empty();
474	        let has_explicit_ignores = !self.inner.explicit_ignores.is_empty();
475	
476	        opts.ignore
477	            || opts.git_global
478	            || opts.git_ignore
479	            || opts.git_exclude
480	            || has_custom_ignore_files
481	            || has_explicit_ignores
482	    }
483	
484	    /// Like `matched`, but works with a directory entry instead.
485	    pub(crate) fn matched_dir_entry<'a>(
486	        &'a self,
487	        dent: &DirEntry,
488	    ) -> Match<IgnoreMatch<'a>> {
489	        let m = self.matched(dent.path(), dent.is_dir());
490	        if m.is_none() && self.inner.opts.hidden && is_hidden_entry(dent) {
491	            return Match::Ignore(IgnoreMatch::hidden());
492	        }
493	        m
494	    }
495	
496	    /// Returns a match indicating whether the given file path should be
497	    /// ignored or not.
498	    ///
499	    /// The match contains information about its origin.
500	    pub(crate) fn matched<'a, P: AsRef<Path>>(
501	        &'a self,
502	        path: P,
503	        is_dir: bool,
504	    ) -> Match<IgnoreMatch<'a>> {
505	        // We need to be careful with our path. If it has a leading ./, then
506	        // strip it because it causes nothing but trouble.
507	        let mut path = path.as_ref();
508	        if let Some(p) = strip_prefix("./", path) {
509	            path = p;
510	        }
511	        // Match against the override patterns. If an override matches
512	        // regardless of whether it's whitelist/ignore, then we quit and
513	        // return that result immediately. Overrides have the highest
514	        // precedence.
515	        if !self.inner.overrides.is_empty() {
516	            let mat = self
517	                .inner
518	                .overrides
519	                .matched(path, is_dir)
520	                .map(IgnoreMatch::overrides);
521	            if !mat.is_none() {
522	                return mat;
523	            }
524	        }
525	        let mut whitelisted = Match::None;
526	        if self.has_any_ignore_rules() {
527	            let mat = self.matched_ignore(path, is_dir);
528	            if mat.is_ignore() {
529	                return mat;
530	            } else if mat.is_whitelist() {
531	                whitelisted = mat;
532	            }
533	        }
534	        if !self.inner.types.is_empty() {
535	            let mat =
536	                self.inner.types.matched(path, is_dir).map(IgnoreMatch::types);
537	            if mat.is_ignore() {
538	                return mat;
539	            } else if mat.is_whitelist() {
540	                whitelisted = mat;
541	            }
542	        }
543	        whitelisted
544	    }
545	
546	    /// Performs matching only on the ignore files for this directory and
547	    /// all parent directories.
548	    pub(crate) fn matched_ignore<'a>(
549	        &'a self,
550	        path: &Path,
551	        is_dir: bool,
552	    ) -> Match<IgnoreMatch<'a>> {
553	        let (
554	            mut m_custom_ignore,
555	            mut m_ignore,
556	            mut m_gi,
557	            mut m_gi_exclude,
558	            mut m_explicit,
559	        ) = (Match::None, Match::None, Match::None, Match::None, Match::None);
560	        let any_git = !self.inner.opts.require_git
561	            || self.parents().any(|ig| ig.inner.has_git);
562	        let mut saw_git = false;
563	        for ig in self.parents().take_while(|ig| !ig.inner.is_absolute_parent)
564	        {
565	            if m_custom_ignore.is_none() {
566	                m_custom_ignore = ig
567	                    .inner
568	                    .custom_ignore_matcher
569	                    .matched(path, is_dir)
570	                    .map(IgnoreMatch::gitignore);
571	            }
572	            if m_ignore.is_none() {
573	                m_ignore = ig
574	                    .inner
575	                    .ignore_matcher
576	                    .matched(path, is_dir)
577	                    .map(IgnoreMatch::gitignore);
578	            }
579	            if any_git && !saw_git && m_gi.is_none() {
580	                m_gi = ig
581	                    .inner
582	                    .git_ignore_matcher
583	                    .matched(path, is_dir)
584	                    .map(IgnoreMatch::gitignore);
585	            }
586	            if any_git && !saw_git && m_gi_exclude.is_none() {
587	                m_gi_exclude = ig
588	                    .inner
589	                    .git_exclude_matcher
590	                    .matched(path, is_dir)
591	                    .map(IgnoreMatch::gitignore);
592	            }
593	            saw_git = saw_git || ig.inner.has_git;
594	        }
595	        if self.inner.opts.parents {
596	            if let Some(abs_parent_path) = self.absolute_base() {
597	                // What we want to do here is take the absolute base path of
598	                // this directory and join it with the path we're searching.
599	                // The main issue we want to avoid is accidentally duplicating
600	                // directory components, so we try to strip any common prefix
601	                // off of `path`. Overall, this seems a little ham-fisted, but
602	                // it does fix a nasty bug. It should do fine until we overhaul
603	                // this crate.
604	                let path = abs_parent_path.join(
605	                    self.parents()
606	                        .take_while(|ig| !ig.inner.is_absolute_parent)
607	                        .last()
608	                        .map_or(path, |ig| {
609	                            // This is a weird special case when ripgrep users
610	                            // search with just a `.`, as some tools do
611	                            // automatically (like consult). In this case, if
612	                            // we don't bail out now, the code below will strip
613	                            // a leading `.` from `path`, which might mangle
614	                            // a hidden file name!
615	                            if ig.inner.dir.as_path() == Path::new(".") {
616	                                return path;
617	                            }
618	                            let without_dot_slash = strip_if_is_prefix(
619	                                "./",
620	                                ig.inner.dir.as_path(),
621	                            );
622	                            let relative_base =
623	                                strip_if_is_prefix(without_dot_slash, path);
624	                            strip_if_is_prefix("/", relative_base)
625	                        }),
626	                );
627	
628	                for ig in self
629	                    .parents()
630	                    .skip_while(|ig| !ig.inner.is_absolute_parent)
631	                {
632	                    if m_custom_ignore.is_none() {
633	                        m_custom_ignore = ig
634	                            .inner
635	                            .custom_ignore_matcher
636	                            .matched(&path, is_dir)
637	                            .map(IgnoreMatch::gitignore);
638	                    }
639	                    if m_ignore.is_none() {
640	                        m_ignore = ig
641	                            .inner
642	                            .ignore_matcher
643	                            .matched(&path, is_dir)
644	                            .map(IgnoreMatch::gitignore);
645	                    }
646	                    if any_git && !saw_git && m_gi.is_none() {
647	                        m_gi = ig
648	                            .inner
649	                            .git_ignore_matcher
650	                            .matched(&path, is_dir)
651	                            .map(IgnoreMatch::gitignore);
652	                    }
653	                    if any_git && !saw_git && m_gi_exclude.is_none() {
654	                        m_gi_exclude = ig
655	                            .inner
656	                            .git_exclude_matcher
657	                            .matched(&path, is_dir)
658	                            .map(IgnoreMatch::gitignore);
659	                    }
660	                    saw_git = saw_git || ig.inner.has_git;
661	                }
662	            }
663	        }
664	        for gi in self.inner.explicit_ignores.iter().rev() {
665	            if !m_explicit.is_none() {
666	                break;
667	            }
668	            m_explicit = gi.matched(&path, is_dir).map(IgnoreMatch::gitignore);
669	        }
670	        let m_global = if any_git {
671	            self.inner
672	                .git_global_matcher
673	                .matched(&path, is_dir)
674	                .map(IgnoreMatch::gitignore)
675	        } else {
676	            Match::None
677	        };
678	
679	        m_custom_ignore
680	            .or(m_ignore)
681	            .or(m_gi)
682	            .or(m_gi_exclude)
683	            .or(m_global)
684	            .or(m_explicit)
685	    }
