813	    /// Builds a new `Ignore` matcher using the given CWD directory.
814	    ///
815	    /// The matcher returned won't match anything until ignore rules from
816	    /// directories are added to it.
817	    pub(crate) fn build_with_cwd(&self, cwd: Option<PathBuf>) -> Ignore {
818	        let global_gitignores_relative_to =
819	            cwd.or_else(|| self.global_gitignores_relative_to.clone());
820	        let git_global_matcher = if !self.opts.git_global {
821	            Gitignore::empty()
822	        } else if let Some(ref cwd) = global_gitignores_relative_to {
823	            let mut builder = GitignoreBuilder::new(cwd);
824	            builder
825	                .case_insensitive(self.opts.ignore_case_insensitive)
826	                .unwrap();
827	            let (gi, err) = builder.build_global();
828	            if let Some(err) = err {
829	                log::debug!("{}", err);
830	            }
831	            gi
832	        } else {
833	            log::debug!(
834	                "ignoring global gitignore file because CWD is not known"
835	            );
836	            Gitignore::empty()
837	        };
838	
839	        Ignore {
840	            inner: Arc::new(IgnoreInner {
841	                compiled: Arc::new(RwLock::new(HashMap::new())),
842	                dir: self.dir.clone(),
843	                overrides: self.overrides.clone(),
844	                types: self.types.clone(),
845	                parent: None,
846	                is_absolute_parent: true,
847	                global_gitignores_relative_to,
848	                explicit_ignores: Arc::new(self.explicit_ignores.clone()),
849	                custom_ignore_filenames: Arc::new(
850	                    self.custom_ignore_filenames.clone(),
851	                ),
852	                custom_ignore_matcher: Gitignore::empty(),
853	                ignore_matcher: Gitignore::empty(),
854	                git_global_matcher: Arc::new(git_global_matcher),
855	                git_ignore_matcher: Gitignore::empty(),
856	                git_exclude_matcher: Gitignore::empty(),
857	                has_git: false,
858	                opts: self.opts,
859	            }),
860	            absolute_base: None,
861	        }
862	    }
