1053	/// Find the GIT_COMMON_DIR for the given git worktree.
1054	///
1055	/// This is the directory that may contain a private ignore file
1056	/// "info/exclude". Unlike git, this function does *not* read environment
1057	/// variables GIT_DIR and GIT_COMMON_DIR, because it is not clear how to use
1058	/// them when multiple repositories are searched.
1059	///
1060	/// Some I/O errors are ignored.
1061	fn resolve_git_commondir(
1062	    dir: &Path,
1063	    git_type: Option<FileType>,
1064	) -> Result<PathBuf, Option<Error>> {
1065	    let git_dir_path = || dir.join(".git");
1066	    let git_dir = git_dir_path();
1067	    if !git_type.map_or(false, |ft| ft.is_file()) {
1068	        return Ok(git_dir);
1069	    }
1070	    let file = match File::open(git_dir) {
1071	        Ok(file) => io::BufReader::new(file),
1072	        Err(err) => {
1073	            return Err(Some(Error::Io(err).with_path(git_dir_path())));
1074	        }
1075	    };
1076	    let dot_git_line = match file.lines().next() {
1077	        Some(Ok(line)) => line,
1078	        Some(Err(err)) => {
1079	            return Err(Some(Error::Io(err).with_path(git_dir_path())));
1080	        }
1081	        None => return Err(None),
1082	    };
1083	    if !dot_git_line.starts_with("gitdir: ") {
1084	        return Err(None);
1085	    }
1086	    let real_git_dir = PathBuf::from(&dot_git_line["gitdir: ".len()..]);
1087	    let git_commondir_file = || real_git_dir.join("commondir");
1088	    let file = match File::open(git_commondir_file()) {
1089	        Ok(file) => io::BufReader::new(file),
1090	        Err(_) => return Err(None),
1091	    };
1092	    let commondir_line = match file.lines().next() {
1093	        Some(Ok(line)) => line,
1094	        Some(Err(err)) => {
1095	            return Err(Some(Error::Io(err).with_path(git_commondir_file())));
1096	        }
1097	        None => return Err(None),
1098	    };
1099	    let commondir_abs = if commondir_line.starts_with(".") {
1100	        real_git_dir.join(commondir_line) // relative commondir
1101	    } else {
1102	        PathBuf::from(commondir_line)
1103	    };
1104	    Ok(commondir_abs)
1105	}
