1242	                        self.ig.add_child(ent.path())
1243	                    };
1244	                    self.ig = igtmp;
1245	                    ent.err = err;
1246	                    return Some(Ok(ent));
1247	                }
1248	                Ok(WalkEvent::File(ent)) => {
1249	                    let ent = DirEntry::new_walkdir(ent, None);
1250	                    let should_skip = match self.skip_entry(&ent) {
1251	                        Err(err) => return Some(Err(err)),
1252	                        Ok(should_skip) => should_skip,
1253	                    };
1254	                    if should_skip {
1255	                        continue;
1256	                    }
1257	                    return Some(Ok(ent));
1258	                }
1259	            }
1260	        }
1261	    }
1262	}
