1424	impl WalkParallel {
1425	    /// Execute the parallel recursive directory iterator. `mkf` is called
1426	    /// for each thread used for iteration. The function produced by `mkf`
1427	    /// is then in turn called for each visited file path.
1428	    pub fn run<'s, F>(self, mkf: F)
1429	    where
1430	        F: FnMut() -> FnVisitor<'s>,
1431	    {
1432	        self.visit(&mut FnBuilder { builder: mkf })
1433	    }
