1435	    /// Execute the parallel recursive directory iterator using a custom
1436	    /// visitor.
1437	    ///
1438	    /// The builder given is used to construct a visitor for every thread
1439	    /// used by this traversal. The visitor returned from each builder is then
1440	    /// called for every directory entry seen by that thread.
1441	    ///
1442	    /// Typically, creating a custom visitor is useful if you need to perform
1443	    /// some kind of cleanup once traversal is finished. This can be achieved
1444	    /// by implementing `Drop` for your builder (or for your visitor, if you
1445	    /// want to execute cleanup for every thread that is launched).
1446	    ///
1447	    /// For example, each visitor might build up a data structure of results
1448	    /// corresponding to the directory entries seen for each thread. Since each
1449	    /// visitor runs on only one thread, this build-up can be done without
1450	    /// synchronization. Then, once traversal is complete, all of the results
1451	    /// can be merged together into a single data structure.
1452	    pub fn visit(mut self, builder: &mut dyn ParallelVisitorBuilder<'_>) {
1453	        let threads = self.threads();
1454	        let mut stack = vec![];
1455	        {
1456	            let mut visitor = builder.build();
1457	            let mut paths = Vec::new().into_iter();
1458	            std::mem::swap(&mut paths, &mut self.paths);
1459	            // Send the initial set of root paths to the pool of workers. Note
1460	            // that we only send directories. For files, we send to them the
1461	            // callback directly.
1462	            for path in paths {
1463	                let (dent, root_device) = if path == Path::new("-") {
1464	                    (DirEntry::new_stdin(), None)
1465	                } else {
1466	                    let root_device = if !self.same_file_system {
1467	                        None
1468	                    } else {
1469	                        match device_num(&path) {
1470	                            Ok(root_device) => Some(root_device),
1471	                            Err(err) => {
1472	                                let err = Error::Io(err).with_path(path);
1473	                                if visitor.visit(Err(err)).is_quit() {
1474	                                    return;
1475	                                }
1476	                                continue;
1477	                            }
1478	                        }
1479	                    };
1480	                    match DirEntryRaw::from_path(0, path, false) {
1481	                        Ok(dent) => {
1482	                            (DirEntry::new_raw(dent, None), root_device)
1483	                        }
1484	                        Err(err) => {
1485	                            if visitor.visit(Err(err)).is_quit() {
1486	                                return;
1487	                            }
1488	                            continue;
1489	                        }
1490	                    }
1491	                };
1492	                stack.push(Message::Work(Work {
1493	                    dent,
1494	                    ignore: self.ig_root.clone(),
1495	                    root_device,
1496	                }));
1497	            }
1498	            // ... but there's no need to start workers if we don't need them.
1499	            if stack.is_empty() {
1500	                return;
1501	            }
1502	        }
1503	        // Create the workers and then wait for them to finish.
1504	        let quit_now = Arc::new(AtomicBool::new(false));
1505	        let active_workers = Arc::new(AtomicUsize::new(threads));
1506	        let stacks = Stack::new_for_each_thread(threads, stack);
1507	        // Collect all of the workers first. In the case that
1508	        // `builder.build()` panics, we want that to happen and
1509	        // propagate before we actually start to run any of the
1510	        // workers.
1511	        let workers: Vec<_> = stacks
1512	            .into_iter()
1513	            .map(|stack| Worker {
1514	                visitor: builder.build(),
1515	                stack,
1516	                quit_now: quit_now.clone(),
1517	                active_workers: active_workers.clone(),
1518	                max_depth: self.max_depth,
1519	                min_depth: self.min_depth,
1520	                max_filesize: self.max_filesize,
1521	                follow_links: self.follow_links,
1522	                skip: self.skip.clone(),
1523	                filter: self.filter.clone(),
1524	            })
1525	            .collect();
1526	        std::thread::scope(|s| {
1527	            let handles: Vec<_> = workers
1528	                .into_iter()
1529	                .map(|worker| s.spawn(|| worker.run()))
1530	                .collect();
1531	            for handle in handles {
1532	                handle.join().unwrap();
1533	            }
1534	        });
1535	    }
1536	
1537	    fn threads(&self) -> usize {
1538	        if self.threads == 0 {
1539	            std::thread::available_parallelism().map_or(1, |n| n.get()).min(12)
1540	        } else {
1541	            self.threads
1542	        }
1543	    }
1544	}
