1587	    /// Adds ignore rules for parent directories.
1588	    ///
1589	    /// Note that this only applies to entries at depth 0. On all other
1590	    /// entries, this is a no-op.
1591	    fn add_parents(&mut self) -> Option<Error> {
1592	        if self.dent.depth() > 0 {
1593	            return None;
1594	        }
1595	        // At depth 0, the path of this entry is a root path, so we can
1596	        // use it directly to add parent ignore rules.
1597	        let (ig, err) = self.ignore.add_parents(self.dent.path());
