1602	    /// Adds ignore rules for this directory without reading its contents.
1603	    fn add_ignore(&mut self) {
1604	        let (ig, err) = self.ignore.add_child(self.dent.path());
1605	        self.ignore = ig;
1606	        self.dent.err = err;
1607	    }
1608	
1609	    /// Reads the directory contents of this work item and adds ignore
1610	    /// rules for this directory.
1611	    ///
1612	    /// If there was a problem with reading the directory contents, then
1613	    /// an error is returned. If there was a problem reading the ignore
1614	    /// rules for this directory, then the error is attached to this
1615	    /// work item's directory entry.
1616	    fn read_dir(&mut self) -> Result<ReadDirResult, Error> {
1617	        let readdir = match fs::read_dir(self.dent.path()) {
1618	            Ok(readdir) => readdir,
1619	            Err(err) => {
1620	                let err = Error::from(err)
1621	                    .with_path(self.dent.path())
1622	                    .with_depth(self.dent.depth());
1623	                return Err(err);
1624	            }
1625	        };
1626	        // Actually descend into the directory and read its contents
1627	        let mut result = ReadDirResult::default();
1628	        for entry in readdir {
1629	            match entry {
1630	                Ok(entry) => result.entries.push(entry),
1631	                Err(err) => result.errors.push(
1632	                    Error::from(err)
1633	                        .with_path(self.dent.path())
1634	                        .with_depth(self.dent.depth() + 1),
1635	                ),
1636	            }
1637	        }
1638	        let (ig, err) = self
1639	            .ignore
1640	            .add_child_with_entries(self.dent.path(), &result.entries);
1641	        self.ignore = ig;
1642	        self.dent.err = err;
1643	        Ok(result)
1644	    }
1645	}
