1647	/// A work-stealing stack.
1648	#[derive(Debug)]
1649	struct Stack {
1650	    /// This thread's index.
1651	    index: usize,
1652	    /// The thread-local stack.
1653	    deque: Deque<Message>,
1654	    /// The work stealers.
1655	    stealers: Arc<[Stealer<Message>]>,
1656	}
1657	
1658	impl Stack {
1659	    /// Create a work-stealing stack for each thread. The given messages
1660	    /// correspond to the initial paths to start the search at. They will
1661	    /// be distributed automatically to each stack in a round-robin fashion.
1662	    fn new_for_each_thread(threads: usize, init: Vec<Message>) -> Vec<Stack> {
1663	        // Using new_lifo() ensures each worker operates depth-first, not
1664	        // breadth-first. We do depth-first because a breadth first traversal
1665	        // on wide directories with a lot of gitignores is disastrous (for
1666	        // example, searching a directory tree containing all of crates.io).
1667	        let deques: Vec<Deque<Message>> =
1668	            std::iter::repeat_with(Deque::new_lifo).take(threads).collect();
1669	        let stealers = Arc::<[Stealer<Message>]>::from(
1670	            deques.iter().map(Deque::stealer).collect::<Vec<_>>(),
1671	        );
1672	        let stacks: Vec<Stack> = deques
1673	            .into_iter()
1674	            .enumerate()
1675	            .map(|(index, deque)| Stack {
1676	                index,
1677	                deque,
1678	                stealers: stealers.clone(),
1679	            })
1680	            .collect();
1681	        // Distribute the initial messages, reverse the order to cancel out
1682	        // the other reversal caused by the inherent LIFO processing of the
1683	        // per-thread stacks which are filled here.
1684	        init.into_iter()
1685	            .rev()
1686	            .zip(stacks.iter().cycle())
1687	            .for_each(|(m, s)| s.push(m));
1688	        stacks
1689	    }
1690	
1691	    /// Push a message.
1692	    fn push(&self, msg: Message) {
1693	        self.deque.push(msg);
1694	    }
1695	
1696	    /// Pop a message.
1697	    fn pop(&self) -> Option<Message> {
1698	        self.deque.pop().or_else(|| self.steal())
1699	    }
1700	
1701	    /// Steal a message from another queue.
1702	    fn steal(&self) -> Option<Message> {
1703	        // For fairness, try to steal from index + 1, index + 2, ... len - 1,
1704	        // then wrap around to 0, 1, ... index - 1.
1705	        let (left, right) = self.stealers.split_at(self.index);
1706	        // Don't steal from ourselves
1707	        let right = &right[1..];
1708	
1709	        right
1710	            .iter()
1711	            .chain(left.iter())
1712	            .map(|s| s.steal_batch_and_pop(&self.deque))
1713	            .find_map(|s| s.success())
1714	    }
1715	}
