1717	/// A worker is responsible for descending into directories, updating the
1718	/// ignore matchers, producing new work and invoking the caller's callback.
1719	///
1720	/// Note that a worker is *both* a producer and a consumer.
1721	struct Worker<'s> {
1722	    /// The caller's callback.
1723	    visitor: Box<dyn ParallelVisitor + 's>,
1724	    /// A work-stealing stack of work to do.
1725	    ///
1726	    /// We use a stack instead of a channel because a stack lets us visit
1727	    /// directories in depth first order. This can substantially reduce peak
1728	    /// memory usage by keeping both the number of file paths and gitignore
1729	    /// matchers in memory lower.
1730	    stack: Stack,
1731	    /// Whether all workers should terminate at the next opportunity. Note
1732	    /// that we need this because we don't want other `Work` to be done after
1733	    /// we quit. We wouldn't need this if have a priority channel.
1734	    quit_now: Arc<AtomicBool>,
1735	    /// The number of currently active workers.
1736	    active_workers: Arc<AtomicUsize>,
1737	    /// The maximum depth of directories to descend. A value of `0` means no
1738	    /// descension at all.
1739	    max_depth: Option<usize>,
1740	    /// The minimum depth of directories to descend.
1741	    min_depth: Option<usize>,
1742	    /// The maximum size a searched file can be (in bytes). If a file exceeds
1743	    /// this size it will be skipped.
1744	    max_filesize: Option<u64>,
1745	    /// Whether to follow symbolic links or not. When this is enabled, loop
1746	    /// detection is performed.
1747	    follow_links: bool,
1748	    /// A file handle to skip, currently is either `None` or stdout, if it's
1749	    /// a file and it has been requested to skip files identical to stdout.
1750	    skip: Option<Arc<Handle>>,
1751	    /// A predicate applied to dir entries. If true, the entry and all
1752	    /// children will be skipped.
1753	    filter: Option<Filter>,
1754	}
1755	
1756	impl<'s> Worker<'s> {
1757	    /// Runs this worker until there is no more work left to do.
1758	    ///
1759	    /// The worker will call the caller's callback for all entries that aren't
1760	    /// skipped by the ignore matcher.
1761	    fn run(mut self) {
1762	        while let Some(work) = self.get_work() {
1763	            if let WalkState::Quit = self.run_one(work) {
1764	                self.quit_now();
1765	            }
1766	        }
1767	    }
1768	
1769	    fn run_one(&mut self, mut work: Work) -> WalkState {
1770	        let should_visit = self
1771	            .min_depth
1772	            .map(|min_depth| work.dent.depth() >= min_depth)
1773	            .unwrap_or(true);
1774	
1775	        // If the work is not a directory, then we can just execute the
1776	        // caller's callback immediately and move on.
1777	        if work.is_symlink() || !work.is_dir() {
1778	            return if should_visit {
1779	                self.visitor.visit(Ok(work.dent))
1780	            } else {
1781	                WalkState::Continue
1782	            };
1783	        }
1784	        if let Some(err) = work.add_parents() {
1785	            let state = self.visitor.visit(Err(err));
1786	            if state.is_quit() {
1787	                return state;
1788	            }
1789	        }
1790	
1791	        let descend = if let Some(root_device) = work.root_device {
1792	            match is_same_file_system(root_device, work.dent.path()) {
1793	                Ok(true) => true,
1794	                Ok(false) => false,
1795	                Err(err) => {
1796	                    let state = self.visitor.visit(Err(err));
1797	                    if state.is_quit() {
1798	                        return state;
1799	                    }
1800	                    false
1801	                }
1802	            }
1803	        } else {
1804	            true
1805	        };
1806	
1807	        // Try to read the directory first before we transfer ownership
1808	        // to the provided closure. Do not unwrap it immediately, though,
1809	        // as we may receive an `Err` value e.g. in the case when we do not
1810	        // have sufficient read permissions to list the directory.
1811	        // In that case we still want to provide the closure with a valid
1812	        // entry before passing the error value.
1813	        let depth = work.dent.depth();
1814	        let readdir = if descend && self.max_depth.is_none_or(|m| depth < m) {
1815	            Some(work.read_dir())
1816	        } else {
1817	            work.add_ignore();
1818	            None
1819	        };
1820	        if should_visit {
1821	            let state = self.visitor.visit(Ok(work.dent));
1822	            if !state.is_continue() {
1823	                return state;
1824	            }
1825	        }
1826	        if !descend {
1827	            return WalkState::Skip;
1828	        }
1829	
1830	        let readdir = match readdir {
1831	            Some(readdir) => readdir,
1832	            None => return WalkState::Skip,
1833	        };
1834	        let readdir = match readdir {
1835	            Ok(readdir) => readdir,
1836	            Err(err) => {
1837	                return self.visitor.visit(Err(err));
1838	            }
1839	        };
1840	
1841	        for result in readdir.entries {
1842	            let state = self.generate_work(
1843	                &work.ignore,
1844	                depth + 1,
1845	                work.root_device,
1846	                result,
1847	            );
1848	            if state.is_quit() {
1849	                return state;
1850	            }
1851	        }
1852	        for err in readdir.errors {
1853	            let state = self.visitor.visit(Err(err));
1854	            if state.is_quit() {
1855	                return state;
1856	            }
1857	        }
1858	        WalkState::Continue
1859	    }
1860	
1861	    /// Decides whether to submit the given directory entry as a file to
1862	    /// search.
1863	    ///
1864	    /// If the entry is a path that should be ignored, then this is a no-op.
1865	    /// Otherwise, the entry is pushed on to the queue. (The actual execution
1866	    /// of the callback happens in `run_one`.)
1867	    ///
1868	    /// If an error occurs while reading the entry, then it is sent to the
1869	    /// caller's callback.
1870	    ///
1871	    /// `ig` is the `Ignore` matcher for the parent directory. `depth` should
1872	    /// be the depth of this entry. `result` should be the item yielded by
1873	    /// a directory iterator.
1874	    fn generate_work(
1875	        &mut self,
1876	        ig: &Ignore,
1877	        depth: usize,
1878	        root_device: Option<u64>,
1879	        fs_dent: fs::DirEntry,
1880	    ) -> WalkState {
1881	        let mut dent = match DirEntryRaw::from_entry(depth, &fs_dent) {
1882	            Ok(dent) => DirEntry::new_raw(dent, None),
1883	            Err(err) => {
1884	                return self.visitor.visit(Err(err));
1885	            }
1886	        };
1887	        let is_symlink = dent.file_type().map_or(false, |ft| ft.is_symlink());
1888	        if self.follow_links && is_symlink {
1889	            let path = dent.path().to_path_buf();
1890	            dent = match DirEntryRaw::from_path(depth, path, true) {
1891	                Ok(dent) => DirEntry::new_raw(dent, None),
1892	                Err(err) => {
1893	                    return self.visitor.visit(Err(err));
1894	                }
1895	            };
1896	            if dent.is_dir() {
1897	                if let Err(err) = check_symlink_loop(ig, dent.path(), depth) {
1898	                    return self.visitor.visit(Err(err));
1899	                }
1900	            }
1901	        }
1902	        // N.B. See analogous call in the single-threaded implementation about
1903	        // why it's important for this to come before the checks below.
1904	        if should_skip_entry(ig, &dent) {
1905	            return WalkState::Continue;
1906	        }
1907	        if let Some(ref stdout) = self.skip {
1908	            let is_stdout = match path_equals(&dent, stdout) {
1909	                Ok(is_stdout) => is_stdout,
1910	                Err(err) => return self.visitor.visit(Err(err)),
1911	            };
1912	            if is_stdout {
1913	                return WalkState::Continue;
1914	            }
1915	        }
1916	        let should_skip_filesize =
1917	            if self.max_filesize.is_some() && !dent.is_dir() {
1918	                skip_filesize(
1919	                    self.max_filesize.unwrap(),
1920	                    dent.path(),
1921	                    &dent.metadata().ok(),
1922	                )
1923	            } else {
1924	                false
1925	            };
1926	        let should_skip_filtered =
1927	            if let Some(Filter(predicate)) = &self.filter {
1928	                !predicate(&dent)
1929	            } else {
1930	                false
1931	            };
1932	        if !should_skip_filesize && !should_skip_filtered {
1933	            self.send(Work { dent, ignore: ig.clone(), root_device });
1934	        }
1935	        WalkState::Continue
1936	    }
1937	
1938	    /// Returns the next directory to descend into.
1939	    ///
1940	    /// If all work has been exhausted, then this returns None. The worker
1941	    /// should then subsequently quit.
1942	    fn get_work(&mut self) -> Option<Work> {
1943	        let mut value = self.recv();
1944	        loop {
1945	            // Simulate a priority channel: If quit_now flag is set, we can
1946	            // receive only quit messages.
1947	            if self.is_quit_now() {
1948	                value = Some(Message::Quit)
1949	            }
1950	            match value {
1951	                Some(Message::Work(work)) => {
1952	                    return Some(work);
1953	                }
1954	                Some(Message::Quit) => {
1955	                    // Repeat quit message to wake up sleeping threads, if
1956	                    // any. The domino effect will ensure that every thread
1957	                    // will quit.
1958	                    self.send_quit();
1959	                    return None;
1960	                }
1961	                None => {
1962	                    if self.deactivate_worker() == 0 {
1963	                        // If deactivate_worker() returns 0, every worker thread
1964	                        // is currently within the critical section between the
1965	                        // acquire in deactivate_worker() and the release in
1966	                        // activate_worker() below.  For this to happen, every
1967	                        // worker's local deque must be simultaneously empty,
1968	                        // meaning there is no more work left at all.
1969	                        self.send_quit();
1970	                        return None;
1971	                    }
1972	                    // Wait for next `Work` or `Quit` message.
1973	                    loop {
1974	                        if self.is_quit_now() {
1975	                            return None;
1976	                        }
1977	                        if let Some(v) = self.recv() {
1978	                            self.activate_worker();
1979	                            value = Some(v);
1980	                            break;
1981	                        }
1982	                        // Our stack isn't blocking. Instead of burning the
1983	                        // CPU waiting, we let the thread sleep for a bit. In
1984	                        // general, this tends to only occur once the search is
1985	                        // approaching termination.
1986	                        let dur = std::time::Duration::from_millis(1);
1987	                        std::thread::sleep(dur);
1988	                    }
1989	                }
1990	            }
1991	        }
1992	    }
1993	
1994	    /// Indicates that all workers should quit immediately.
1995	    fn quit_now(&self) {
1996	        self.quit_now.store(true, AtomicOrdering::SeqCst);
1997	    }
1998	
1999	    /// Returns true if this worker should quit immediately.
2000	    fn is_quit_now(&self) -> bool {
2001	        self.quit_now.load(AtomicOrdering::SeqCst)
2002	    }
2003	
2004	    /// Send work.
2005	    fn send(&self, work: Work) {
2006	        self.stack.push(Message::Work(work));
2007	    }
2008	
2009	    /// Send a quit message.
2010	    fn send_quit(&self) {
2011	        self.stack.push(Message::Quit);
2012	    }
2013	
2014	    /// Receive work.
2015	    fn recv(&self) -> Option<Message> {
2016	        self.stack.pop()
2017	    }
2018	
2019	    /// Deactivates a worker and returns the number of currently active workers.
2020	    fn deactivate_worker(&self) -> usize {
2021	        self.active_workers.fetch_sub(1, AtomicOrdering::Acquire) - 1
2022	    }
2023	
2024	    /// Reactivates a worker.
2025	    fn activate_worker(&self) {
2026	        self.active_workers.fetch_add(1, AtomicOrdering::Release);
2027	    }
2028	}
2029	
2030	impl<'s> Drop for Worker<'s> {
2031	    fn drop(&mut self) {
2032	        if std::thread::panicking() {
2033	            self.quit_now();
2034	        }
2035	    }
2036	}
