2038	fn check_symlink_loop(
2039	    ig_parent: &Ignore,
2040	    child_path: &Path,
2041	    child_depth: usize,
2042	) -> Result<(), Error> {
2043	    let hchild = Handle::from_path(child_path).map_err(|err| {
2044	        Error::from(err).with_path(child_path).with_depth(child_depth)
2045	    })?;
2046	    for ig in ig_parent.parents().take_while(|ig| !ig.is_absolute_parent()) {
2047	        let h = Handle::from_path(ig.path()).map_err(|err| {
2048	            Error::from(err).with_path(child_path).with_depth(child_depth)
2049	        })?;
2050	        if hchild == h {
2051	            return Err(Error::Loop {
2052	                ancestor: ig.path().to_path_buf(),
2053	                child: child_path.to_path_buf(),
2054	            }
2055	            .with_depth(child_depth));
2056	        }
2057	    }
2058	    Ok(())
2059	}
2060	
2061	// Before calling this function, make sure that you ensure that is really
2062	// necessary as the arguments imply a file stat.
2063	fn skip_filesize(
2064	    max_filesize: u64,
2065	    path: &Path,
2066	    ent: &Option<Metadata>,
2067	) -> bool {
2068	    let filesize = match *ent {
2069	        Some(ref md) => Some(md.len()),
2070	        None => None,
2071	    };
2072	
2073	    if let Some(fs) = filesize {
2074	        if fs > max_filesize {
2075	            log::debug!("ignoring {}: {} bytes", path.display(), fs);
2076	            true
2077	        } else {
2078	            false
2079	        }
2080	    } else {
2081	        false
2082	    }
2083	}
2084	
2085	fn should_skip_entry(ig: &Ignore, dent: &DirEntry) -> bool {
2086	    let m = ig.matched_dir_entry(dent);
2087	    if m.is_ignore() {
2088	        log::debug!("ignoring {}: {:?}", dent.path().display(), m);
2089	        true
2090	    } else if m.is_whitelist() {
2091	        log::debug!("whitelisting {}: {:?}", dent.path().display(), m);
2092	        false
2093	    } else {
2094	        false
2095	    }
2096	}
