89	/// Cached traversal state for a directory relative to the configured root.
90	///
91	/// The presence of an entry means that the directory and every ancestor
92	/// between it and the root have already been checked.
93	#[derive(Clone, Debug)]
94	enum CachedDir {
95	    /// The directory may be descended into. The matcher includes the ignore
96	    /// rules loaded through this directory and is therefore the matcher to use
97	    /// for its children.
98	    Allowed(Ignore),
99	    /// The directory may not be descended into because it was ignored by a
100	    /// path rule or hidden-file filtering. Every descendant is consequently
101	    /// ignored, and ignore files inside this directory are not loaded.
102	    Ignored,
103	}
