138	    /// Normalize `path` and return it relative to this matcher's root.
139	    ///
140	    /// This returns `None` when `path` cannot be made absolute or
141	    /// when it is known to be outside this matcher's root. Unlike
142	    /// [`IncrementalIgnore::matched`], this performs absolute path conversion,
143	    /// lexical normalization and allocation. It is intended as an opt-in
144	    /// convenience for callers that do not already have root-relative paths.
145	    ///
146	    /// Note that `.` is interpreted relative to the process level current
147	    /// working directory. It is _not_ interpreted relative to the root of
148	    /// this matcher.
149	    ///
150	    /// Note also that this may reject paths that only differ in casing. For
151	    /// example, if the root path for this matcher is `/FOO` but the provided
152	    /// path is `/foo/bar`, then this may return `None`. Callers must ensure
153	    /// casing is consistent between the path provided and the root path for
154	    /// this matcher.
155	    pub fn normalize<P: AsRef<Path>>(&self, path: P) -> Option<PathBuf> {
156	        if matches!(self.ignore, RootIgnore::Stdin) {
157	            return None;
158	        }
159	        let path = normalize_absolute(path.as_ref())?;
160	        let root = self
161	            .normalized_root
162	            .get_or_init(|| normalize_absolute(&self.root))
163	            .as_ref()?;
164	        path.strip_prefix(root).ok().map(Path::to_path_buf)
165	    }
