167	    /// Match a root-relative path against ignore files in its directory and
168	    /// all relevant parent directories.
169	    ///
170	    /// `is_dir` should be true when `path` should be matched as a directory.
171	    ///
172	    /// For the return value, use [`IncrementalMatch::is_ignore`],
173	    /// [`IncrementalMatch::is_whitelist`] or [`IncrementalMatch::is_none`] to
174	    /// inspect it.
175	    ///
176	    /// Matchers for previously unseen directories are loaded and cached during
177	    /// this call. Errors encountered while loading ignore files are logged. To
178	    /// receive those errors, use [`IncrementalIgnore::matched_with_errors`].
179	    ///
180	    /// `path` must be relative to this matcher's root and must not contain a
181	    /// parent directory (`..`) component. Behavior is unspecified when these
182	    /// preconditions are violated. Callers with an absolute path or with a
183	    /// path containing `.` or `..` may use [`IncrementalIgnore::normalize`]
184	    /// to get a path satisfying these preconditions. In all cases, a relative
185	    /// path is *assumed* to be relative to the root of this ignore matcher.
186	    ///
187	    /// In general, it is intended that callers doing recursive directory
188	    /// traversal on the root of this matcher may provide relative paths to
189	    /// this routine *without* calling [`IncrementalIgnore::normalize`].
190	    ///
191	    /// The empty path represents the explicitly configured root and also
192	    /// returns non-match, consistent with recursive traversal where a root is
193	    /// always treated as being at depth zero.
194	    pub fn matched<P: AsRef<Path>>(
195	        &mut self,
196	        path: P,
197	        is_dir: bool,
198	    ) -> IncrementalMatch {
199	        let (matched, err) = self.matched_with_errors(path, is_dir);
200	        if let Some(err) = err {
201	            log::debug!("error while loading ignore files: {err}");
202	        }
203	        matched
204	    }
