206	    /// Match a root-relative path and return errors encountered while loading
207	    /// ignore files.
208	    ///
209	    /// This is equivalent to [`IncrementalIgnore::matched`], except that
210	    /// it returns any errors from newly loaded ignore files. Loading can
211	    /// partially succeed, so valid rules are always applied to the returned
212	    /// match even when an error is present.
213	    pub fn matched_with_errors<P: AsRef<Path>>(
214	        &mut self,
215	        path: P,
216	        is_dir: bool,
217	    ) -> (IncrementalMatch, Option<Error>) {
218	        let mut errs = PartialErrorBuilder::default();
219	        let matched =
220	            self.matched_with_errors_impl(path.as_ref(), is_dir, &mut errs);
221	        (matched, errs.into_error_option())
222	    }
223	
224	    fn matched_with_errors_impl(
225	        &mut self,
226	        relative: &Path,
227	        is_dir: bool,
228	        errs: &mut PartialErrorBuilder,
229	    ) -> IncrementalMatch {
230	        // We short-circuit here when our matcher corresponds to `Stdin` in
231	        // order to always return a non-match. This is somewhat redundant with
232	        // `root_ignore()` which does this too, but we do it here so that it
233	        // always happens, e.g., before depth filtering.
234	        if relative.is_absolute() || matches!(self.ignore, RootIgnore::Stdin) {
235	            return IncrementalMatch::none(is_dir);
236	        }
237	
238	        let (mut satisfies_min, mut edge_max) = (true, false);
239	        if self.options.min_depth.is_some() || self.options.max_depth.is_some()
240	        {
241	            let depth = relative
242	                .components()
243	                .filter_map(|component| match component {
244	                    std::path::Component::CurDir => None,
245	                    component => Some(component),
246	                })
247	                .count();
248	            satisfies_min =
249	                self.options.min_depth.is_none_or(|min| depth >= min);
250	            let satisfies_max =
251	                self.options.max_depth.is_none_or(|max| depth <= max);
252	            edge_max = self.options.max_depth.is_some_and(|max| depth == max);
253	            // When we have a file that isn't past our min depth, we can give
254	            // up right away.
255	            if !is_dir && !satisfies_min {
256	                return IncrementalMatch::ignore().not_within_depth();
257	            }
258	            // Same for *anything* that exceeds our max depth.
259	            if !satisfies_max {
260	                return IncrementalMatch::ignore().not_within_depth();
261	            }
262	        }
263	
264	        // When the path is invalid in some way, we bail out early to avoid
265	        // potentially doing a stat call below.
266	        let (mut mat, valid) = self
267	            .matched_with_errors_ignore(relative, is_dir, errs)
268	            .map(|mat| (mat, true))
269	            .unwrap_or_else(|| (IncrementalMatch::none(is_dir), false));
270	
271	        if !is_dir
272	            && !mat.is_ignore()
273	            && valid
274	            && let Some(max_filesize) = self.options.max_filesize
275	        {
276	            let path = self.root().join(relative);
277	            let result = if self.options.follow_links {
278	                path.metadata()
279	            } else {
280	                path.symlink_metadata()
281	            };
282	            match result {
283	                Ok(md) if md.len() > max_filesize => {
284	                    return IncrementalMatch::ignore();
285	                }
286	                Ok(_) => {}
287	                Err(err) => {
288	                    // Record the error but otherwise fall through
289	                    let err = Error::from(err);
290	                    errs.push(err.with_path(path));
291	                }
292	            }
293	        }
294	
295	        // We still need to tag our `mat` if it doesn't pass the depth filter,
296	        // or if it's a directory on the edge of a depth filter. This can only
297	        // happen when the path is reported as a directory. Otherwise regular
298	        // files are always handled above.
299	        if is_dir {
300	            if !satisfies_min {
301	                mat = mat.not_within_depth();
302	            }
303	            if edge_max {
304	                mat = mat.no_descent();
305	            }
306	        }
307	        mat
308	    }
309	
310	    fn matched_with_errors_ignore(
311	        &mut self,
312	        relative: &Path,
313	        is_dir: bool,
314	        errs: &mut PartialErrorBuilder,
315	    ) -> Option<IncrementalMatch> {
316	        let mut components = relative
317	            .components()
318	            .filter_map(|component| match component {
319	                std::path::Component::CurDir => None,
320	                component => Some(component),
321	            })
322	            .peekable();
323	        components.peek()?;
324	
325	        // If the exact parent is cached, then all of its ancestors have
326	        // already been checked. An allowed cache entry is the matcher to use
327	        // for children of that directory, while an ignored cache entry is
328	        // terminal for every descendant. In the usual case, this avoids both
329	        // walking every component and allocating a relative directory path.
330	        //
331	        // Only try the fast path when the final component is a normal path
332	        // component. Invalid paths are handled by the component walk below.
333	        let has_normal_final_component =
334	            relative.components().next_back().is_some_and(|component| {
335	                matches!(component, std::path::Component::Normal(_))
336	            });
337	        if has_normal_final_component && let Some(parent) = relative.parent() {
338	            match self.dirs.get(parent) {
339	                Some(CachedDir::Allowed(ignore)) => {
340	                    return Some(self.match_path(ignore, relative, is_dir));
341	                }
342	                Some(CachedDir::Ignored) => {
343	                    return Some(IncrementalMatch::ignore());
344	                }
345	                None => {}
346	            }
347	        }
348	
349	        let mut ignore = self.root_ignore(errs)?;
350	        let mut dir = PathBuf::new();
351	        while let Some(component) = components.next() {
352	            match component {
353	                std::path::Component::ParentDir
354	                | std::path::Component::RootDir
355	                | std::path::Component::Prefix(_) => {
356	                    return None;
357	                }
358	                std::path::Component::CurDir => continue,
359	                std::path::Component::Normal(_) => {}
360	            }
361	            if components.peek().is_none() {
362	                break;
363	            }
364	            dir.push(component.as_os_str());
365	            match self.dirs.get(&dir) {
366	                Some(CachedDir::Allowed(cached)) => {
367	                    ignore = cached.clone();
368	                    continue;
369	                }
370	                Some(CachedDir::Ignored) => {
371	                    return Some(IncrementalMatch::ignore());
372	                }
373	                None => {}
374	            }
375	
376	            let path = self.root.join(&dir);
377	            let mat = ignore.matched(&path, true);
378	            let is_hidden =
379	                self.options.hidden && mat.is_none() && is_hidden_path(&path);
380	            if mat.is_ignore() || is_hidden {
381	                self.dirs.insert(dir.clone(), CachedDir::Ignored);
382	                return Some(IncrementalMatch::ignore());
383	            }
384	            let (child, err) = ignore.add_child(&path);
385	            errs.maybe_push(err);
386	            self.dirs.insert(dir.clone(), CachedDir::Allowed(child.clone()));
387	            ignore = child;
388	        }
389	
390	        Some(self.match_path(&ignore, relative, is_dir))
391	    }
392	
393	    fn match_path(
394	        &self,
395	        ignore: &Ignore,
396	        relative: &Path,
397	        is_dir: bool,
398	    ) -> IncrementalMatch {
399	        let path = self.root.join(relative);
400	        let mut mat = IncrementalMatch::from_match(
401	            ignore.matched(&path, is_dir).map(|_| ()),
402	            is_dir,
403	        );
404	        // Whether a file is hidden or not has low precedence in filtering. We
405	        // only check it if we haven't matched anything above. This permits
406	        // callers to whitelist hidden files or directories.
407	        if self.options.hidden && mat.is_none() && is_hidden_path(&path) {
408	            mat = IncrementalMatch::ignore();
409	        }
410	        mat
411	    }
412	
413	    fn root_ignore(
414	        &mut self,
415	        errs: &mut PartialErrorBuilder,
416	    ) -> Option<Ignore> {
417	        let ignore = match self.ignore {
418	            RootIgnore::Unloaded(ref ignore) => ignore.clone(),
419	            RootIgnore::Loaded(ref ignore) => return Some(ignore.clone()),
420	            RootIgnore::NotDirectory | RootIgnore::Stdin => return None,
421	        };
422	        if !self.root.is_dir() {
423	            self.ignore = RootIgnore::NotDirectory;
424	            return None;
425	        }
426	
427	        let (parents, err) = ignore.add_parents(&self.root);
428	        errs.maybe_push(err);
429	        let (root, err) = parents.add_child(&self.root);
430	        errs.maybe_push(err);
431	        self.ignore = RootIgnore::Loaded(root.clone());
432	        Some(root)
433	    }
434	}
